{
  "name": "configure_telemetry_exporter",
  "description": "Configures OpenTelemetry export endpoints and sample rates for tracing.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "sampling_ratio": { "type": "number", "description": "Proportion of traces to sample between 0.0 and 1.0" },
      "export_timeout_ms": { "type": "integer", "description": "Timeout limit for metric transmission" }
    }
  }
}

{
  "name": "verify_database_backup",
  "description": "Validates database dump checksums and verifies header integrity.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "backup_file_path": { "type": "string", "description": "Absolute path to the compressed backup archive" },
      "verify_indices": { "type": "boolean", "description": "Check index page consistency" }
    }
  }
}

{
  "name": "validate_jwt_claims",
  "description": "Validates JSON Web Token signatures and expiration timestamps.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "issuer_url": { "type": "string", "description": "Expected token issuer endpoint" },
      "required_roles": { "type": "array", "description": "Roles required for endpoint access" }
    }
  }
}

{
  "name": "check_service_health",
  "description": "Performs health checks on database connections and upstream services.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "timeout_seconds": { "type": "integer", "description": "Maximum time to wait for health check responses" },
      "check_database": { "type": "boolean", "description": "Include database ping test" }
    }
  }
}

{
  "name": "configure_cache_backend",
  "description": "Configures Redis or in-memory cache connection parameters.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "ttl_default_seconds": { "type": "integer", "description": "Default time-to-live for cached items" },
      "max_memory_mb": { "type": "integer", "description": "Maximum memory limit for in-memory cache store" }
    }
  }
}
